  // Products Page SEO
  'products.page.title': 'Industrial UAV Components & Systems Catalog | Secure Digital Video Links & AI Modules | CANI',
  'products.page.description': "Explore CANI's comprehensive catalog of industrial UAV components: 50km+ long-range digital HD video links, NDAA-compliant flight controllers, and AI-driven guidance modules. Precision engineered for smart grid monitoring, SAR, and surveying. Wholesale & custom OEM/ODM available.",
  'products.page.keywords': 'Industrial UAV Components Manufacturer,UAV Digital Video Link Supplier,Professional Flight Control System,UAV AI Module,BVLOS Drone Hardware',
  'products.hero.badge': 'CANI Technology · Product Center',
  'products.hero.title': 'Professional Industrial UAV Core Systems & Component Solutions',
  'products.hero.subtitle': 'CANI (Changling Technology) delivers mission-critical industrial UAV components engineered for extreme reliability.',
  'products.hero.overview': "Our product portfolio specializes in low-latency digital HD video links, EMI-resistant flight control systems, and edge-AI recognition modules. Backed by over 15 years of industrial R&D and 200+ patented technologies, our hardware is the preferred choice for global system integrators in high-voltage power inspection, public safety response, and precision surveying. We provide end-to-end support from component selection to complex system integration.",
  'products.h2.techCapability': 'Product Categories by Technical Capability',
  'products.cluster.digitalLink.title': 'Digital HD Image Transmission Systems',
  'products.cluster.digitalLink.desc': 'Utilizing COFDM modulation with AES-256 hardware encryption. Designed for 50km+ BVLOS missions, delivering lossless 1080P/60fps video backhaul, solving the quality and interference issues of analog video transmission.',
  'products.cluster.fc.title': 'Professional Flight Control & Navigation',
  'products.cluster.fc.desc': 'Fully supporting Ardupilot and PX4 open-source ecosystems with integrated EMI shielding structures. NDAA-compliant for government projects, with multi-redundant sensor fusion and GNSS-Denied visual navigation.',
  'products.cluster.ai.title': 'AI-Driven Guidance & Recognition Modules',
  'products.cluster.ai.desc': 'Powerful onboard edge computing capabilities. Supporting real-time target locking, autonomous trajectory planning, and multi-modal recognition, boosting traditional inspection automation by over 85%.',
  'products.cluster.platform.title': 'Complete UAV Platform Systems',
  'products.cluster.platform.desc': 'Turnkey tethered, logistics, and swarm drone platforms engineered for 24/7 persistent surveillance, heavy-lift cargo delivery, and coordinated multi-drone operations in complex environments.',
  'products.cta.title': "Can't Find the Right Product?",
  'products.cta.subtitle': 'Contact our professional team for customized solutions and wholesale quotes.',
  'products.cta.button': 'Request Wholesale Quote for UAV Components',
