  'about.competencies.row1.value': 'Not off-the-shelf — RF links redesigned for industrial/special EMI environments',
  'about.competencies.row2.dim': 'High-Performance RF',
  'about.competencies.row2.spec': '37W peak power, Rogers 4350B substrate, 50km+ transmission range',
  'about.competencies.row2.value': 'Ultra-low latency, high-sensitivity reception for complex EMI signal penetration',
  'about.competencies.row3.dim': 'Form Factor Customization',
  'about.competencies.row3.spec': 'From lightweight FPV mini modules to high-power ground stations, PCBA re-layout per airframe',
  'about.competencies.row3.value': 'Hardware structure adapts to any airframe weight and mounting space',

  'about.competencies.layer2.title': 'Software/Protocol Layer',
  'about.competencies.layer2.tag': 'Deep Software Customization',
