  'about.competencies.row9.spec': 'Requirements → Protocol Definition → HW Prototyping → SW Integration → Field Testing → Delivery',
  'about.competencies.row9.value': 'Complete technical documentation, operator training, and post-delivery link maintenance',

  'about.ecosystem.title': 'One-Stop Customization Model',
  'about.ecosystem.desc': 'CANI doesn\'t just sell modules — we provide firmware engineering, PCB design, and complete system integration. Supporting OEM (your brand), ODM (our design), and turnkey customization (you bring the requirements, we deliver everything).',
  'about.ecosystem.item1.title': 'Hardware One-Stop',
  'about.ecosystem.item1.desc': 'Custom airframe design (multirotor/VTOL/lightweight frames), in-house core modules from PCB to mass production.',
  'about.ecosystem.item2.title': 'Software One-Stop',
  'about.ecosystem.item2.desc': 'Private GCS custom development, deep firmware modification, edge AI algorithm integration.',
  'about.ecosystem.item3.title': 'Delivery One-Stop',
