  'about.faq.title': 'About CANI Technology - FAQ',
  'about.faq.q1': 'What are CANI Technology\'s main R&D focus areas?',
  'about.faq.a1': 'CANI Technology specializes in industrial UAV core communication and sensing technology R&D, with industry-leading capabilities in 37W ultra-high-power video transmission systems and precision EO/IR dual-sensor gimbal systems.',
  'about.faq.q2': 'Does CANI Technology offer OEM customization services?',
  'about.faq.a2': 'Yes. We provide industrial-grade payload and flight control system OEM/ODM customization for global clients, supporting deep third-party sensor integration via MAVLink protocol.',
  'about.faq.q3': 'What industries are CANI Technology products suited for?',
  'about.faq.a3': 'CANI\'s 37W VTX and EO/IR gimbal systems are widely deployed in power line inspection, security & SAR, wildfire prevention, maritime surveillance, and surveying — all BVLOS industrial scenarios.',

  // About Page - Profile, Milestones, Values, Stats, CTA
  'about.profile.title': 'History & Mission',
  'about.profile.p1': 'Since its founding in 2015, CANI Technology has adhered to the philosophy of "technology drives value." We insist on 100% in-house R&D of core components, breaking through long-range communication and high-precision attitude control barriers.',
  'about.profile.p2': 'Our vision: empower every industrial UAV with digital technology for longer range, clearer imaging, and steadier flight. As a leading OEM/ODM service provider, CANI delivers full-chain support from interface definition to complete system integration.',
  'about.profile.p3': 'The company maintains an "innovation-driven, quality-first" philosophy with 50+ invention patents and software copyrights, participating in drafting multiple industry standards.',
