  // Per-SKU dynamic FAQs
  'fcEscDetail.faq.6in1.q1': 'When should my drone use a 6-in-1 ESC?',
  'fcEscDetail.faq.6in1.a1': 'A 6-in-1 ESC is optimal for hexacopter configurations, providing a centralized power hub that simplifies wiring and reduces overall weight compared to six separate ESCs. It is ideal for industrial platforms requiring high current density and space efficiency.',
  'fcEscDetail.faq.6in1.q2': 'Does the CANI 100A ESC support 8S LiPo batteries?',
  'fcEscDetail.faq.6in1.a2': 'Yes. Our 100A series (both separate and stacked) uses high-voltage MOSFETs and low ESR capacitors to safely support up to 8S LiPo (33.6V), meeting extreme thrust demands.',
  'fcEscDetail.faq.stack.q1': 'What is the advantage of a flight tower (stack) over separate components?',
  'fcEscDetail.faq.stack.a1': 'A stack integrates FC and ESC into a single compact unit, reducing wiring complexity, saving weight, and minimizing electromagnetic interference. This results in cleaner builds and more reliable flights.',
  'fcEscDetail.faq.stack.q2': 'Can I use this stack with Betaflight and INAV?',
  'fcEscDetail.faq.stack.a2': 'Yes. All CANI stacks support Betaflight firmware out-of-the-box, and most models also support INAV and ArduPilot for GPS autonomous missions.',

  // EEAT Quality Statement
  'fcEscDetail.eeat.title': 'Quality Assurance',
  'fcEscDetail.eeat.statement': 'Every CANI flight controller and ESC assembly undergoes a 48-hour stress test and factory power consistency calibration to ensure zero-defect, ready-to-fly performance out of the box.',
  'fcEscDetail.eeat.protocol': 'Supports SmartAudio v2.1 and IRC Tramp protocols for seamless OSD control.',
  'fcEscDetail.eeat.protocolTitle': 'Protocol Compatibility',

  // Gimbal SEO Content
  'gimbal.seo.title': 'Industrial UAV Gimbal Pods | Quad-Sensor / Dual-Light / AI Tracking Camera - CANI',
  'gimbal.seo.description': 'CANI industrial-grade UAV gimbal pods: K40T quad-sensor AI gimbal (30x zoom + thermal + 1200m laser rangefinder), K8T-V2 dual-light tracking gimbal, K8-V2 single-light AI tracking gimbal. ±0.005° stabilization, IP65 rated for power inspection, firefighting & law enforcement.',
  'gimbal.seo.keywords': 'UAV gimbal,industrial drone gimbal,quad-sensor gimbal camera,dual-light thermal gimbal,AI tracking gimbal,laser rangefinder gimbal,power inspection gimbal,gimbal OEM manufacturer',
  'gimbal.hero.title': 'Industrial ',
  'gimbal.hero.highlight': 'AI Gimbal Pods',
  'gimbal.hero.suffix': ' Series',
  'gimbal.hero.desc': 'Covering quad-sensor AI, dual-light tracking, and single-light recognition product lines. ±0.005° stabilization precision with IP65 protection for power inspection, firefighting, law enforcement, and border patrol applications.',
  'gimbal.back': 'Back to Accessories',
  'gimbal.viewDetail': 'View Details',
  'gimbal.cta.title': 'Need a Custom Gimbal Solution?',
  'gimbal.cta.desc': 'We offer OEM/ODM customization including sensor configuration, interface protocols, and industrial design. Compatible with MAVLink/SBUS/PWM protocols and Pixhawk flight controllers.',
  'gimbal.cta.btn': 'Request a Quote',
  // Gimbal SKU-specific TDK
  'gimbal.tdk.k40t.title': 'K40T Quad-Sensor AI Gimbal | 48MP Zoom + 640 Thermal + 1.2km Laser | 290g | CANI',
  'gimbal.tdk.k40t.desc': 'CANI K40T quad-sensor AI gimbal integrates 48MP zoom, 640×512 thermal imaging, and 1200m laser rangefinder with 6TOPS AI computing. Only 290g, ±0.005° stabilization, 160x hybrid zoom. Purpose-built for power inspection, fire rescue, and security patrol.',
  'gimbal.tdk.k8t-v2.title': 'K8T-V2 Dual-Sensor Tracking Gimbal | 133g Ultralight | Thermal + AI Tracking | CANI',
  'gimbal.tdk.k8t-v2.desc': 'CANI K8T-V2 weighs just 133g with integrated infrared thermal imaging and visible light recognition. Next-gen AI processor enables autonomous target locking and tracking. 3-axis stabilization, TTL/TCP multi-protocol support for lightweight inspection UAVs and FPV special operations.',
  'gimbal.tdk.k8-v2.title': 'K8-V2 Single-Light AI Tracking Gimbal | 30x Optical Zoom + 4K | CANI',
  'gimbal.tdk.k8-v2.desc': 'K8-V2 AI gimbal with Sony 1/2.8" CMOS sensor, 30x optical + 8x digital zoom, 4K@30fps output. Ultra-lightweight at 115g, IP65 rated, ONVIF protocol support with intelligent target recognition and tracking.',
  'accessoryDetail.gimbal.seoDesc': 'Industrial UAV gimbal pod with triple-axis mechanical stabilization. OEM/ODM customization available.',
  'gimbal.seo.intro.title': 'Product Overview',
  'gimbal.seo.intro': 'CANI Technology industrial UAV gimbal pods deliver precision stabilization for mission-critical aerial operations. Triple-axis mechanical stabilization achieves ±0.005° precision, effectively countering airflow turbulence and fuselage vibration. Our gimbal lineup ranges from 115g single-light trackers to 290g quad-sensor AI systems with 30x optical zoom, 640×512 thermal imaging, and 1200m laser rangefinding — purpose-built for power grid inspection, firefighting, law enforcement, and surveying.',
  'gimbal.techDetail.title': 'Technical Details',
  'gimbal.techDetail': 'Our gimbal pod series features triple-axis mechanical stabilization with ±0.005° jitter control, 360° panoramic rotation, and adjustable pitch (-135° to +45°). Aerospace-grade aluminum alloy construction ensures lightweight durability with IP65 waterproof/dustproof rating for extreme outdoor conditions (-20°C to +55°C). Multiple interfaces supported including Ethernet, serial TTL, HDMI, and SBUS — compatible with MAVLink protocol and Pixhawk-based flight controllers for seamless integration.',
  'gimbal.faq.title': 'Frequently Asked Questions',
  'gimbal.faq.q1': 'Which flight controllers are compatible with CANI gimbal pods?',
  'gimbal.faq.a1': 'All CANI gimbal pods support MAVLink protocol and are compatible with Pixhawk, ArduPilot, and other open-source flight controllers via serial TTL, Ethernet, or SBUS interfaces. Custom protocol integration available for OEM projects.',
  'gimbal.faq.q2': 'Can IP65-rated gimbals operate in rain and extreme temperatures?',
  'gimbal.faq.a2': 'Yes. IP65 rating provides protection against water jets and dust ingress. Operating temperature range is -20°C to +55°C, supporting operations in light rain, snow, and desert environments. For heavy rain scenarios, additional protection is recommended.',
  'gimbal.faq.q3': 'What is the thermal imaging resolution and temperature measurement accuracy?',
  'gimbal.faq.a3': 'The K40T and K8T-V2 models feature 640×512 thermal resolution. K8T-V2 provides radiometric measurement from -20°C to 650°C with ±2°C accuracy, ideal for power equipment thermal fault detection and industrial diagnostics.',
  // GEO FAQ pairs for AI engine extraction
  'gimbal.faq.q4': 'Which CANI gimbal is best for power line inspection at 200m distance?',
  'gimbal.faq.a4': 'The K40T with 30x optical zoom and 4800-megapixel wide-angle sensor can clearly identify insulator cracks, wire strand breaks, and damper displacement at 200m distance. Its 1200m laser rangefinder enables precise distance measurement for clearance analysis.',
  'gimbal.faq.q5': 'How does the K8T-V2 detect transformer overheating via drone?',
  'gimbal.faq.a5': 'The K8T-V2 dual-light gimbal uses its 640×512 radiometric thermal sensor to detect temperature anomalies in transformers, cable joints, and switchgear. With -20°C to 650°C measurement range and ±2°C accuracy, it identifies hotspots 3 weeks before visible damage occurs.',
  'gimbal.faq.q6': 'Is the CANI gimbal NDAA compliant for government use?',
  'gimbal.faq.a6': 'Yes. CANI gimbal pods are manufactured with NDAA-compliant components and data security protocols, making them suitable for government, defense, and critical infrastructure inspection applications worldwide.',
