  'platforms.page.title': 'UAV Platforms & Turnkey Drone Systems',
  'platforms.page.description': 'Explore CANI industrial UAV platforms: tethered drones for 24/7 surveillance, heavy-lift cargo UAVs, autonomous swarm systems, and industrial FPV inspection drones. Redundant power, AES-256 encrypted links.',
  'platforms.page.keywords': 'UAV platforms,turnkey drone systems,tethered drone,cargo drone,swarm UAV,industrial FPV,RTF drone,CANI',
  'platforms.hero.badge': 'UAV Platforms & Systems',
  'platforms.hero.title': 'Industrial UAV Platforms & Turnkey Systems',
  'platforms.hero.subtitle': 'From persistent surveillance to heavy-lift logistics — choose the right ready-to-fly system for your mission',
  'platforms.hero.overview': 'CANI (Changling Technology) designs mission-critical UAV platforms with redundant power architectures, AES-256 encrypted digital HD links, and industrial-grade flight control systems. Our turnkey solutions serve public safety, energy infrastructure, and precision logistics operators worldwide.',

  'platforms.advantages.title': 'Platform-Level Engineering Advantages',
  'platforms.adv.redundant': 'Redundant Power Systems',
  'platforms.adv.redundant.desc': 'Dual-redundant ESCs and battery failover for mission-critical reliability',
  'platforms.adv.endurance': 'Extended Endurance',
  'platforms.adv.endurance.desc': 'Up to 24+ hours tethered, 55+ min free-flight operation',
  'platforms.adv.wind': 'All-Weather Capable',
  'platforms.adv.wind.desc': 'Stable operations in Level 7 winds, IP55 environmental protection',
  'platforms.adv.encryption': 'AES-256 Secure Link',
  'platforms.adv.encryption.desc': 'Hardware-encrypted digital HD video & telemetry transmission',

  'platforms.categories.title': 'Platform Categories by Mission Profile',
  'platforms.categories.subtitle': 'Each platform is purpose-built for specific operational scenarios with optimized airframe, propulsion, and communication architectures.',

  'platforms.tethered.title': 'Tethered UAV Systems',
  'platforms.tethered.desc': '24/7 Persistent Aerial Surveillance & Emergency Communications',
  'platforms.tethered.detail': 'Cable-powered platforms enabling 24-36 hour continuous flight. Physical tether ensures 100% interference-proof data transmission. Ideal for border security, large-event coverage, and rapid temporary base station deployment.',
  'platforms.tethered.anchor': 'Explore Tethered UAV Systems with Unlimited Endurance',

  'platforms.logistics.title': 'Logistics & Cargo UAVs',
  'platforms.logistics.desc': 'Heavy-Lift Autonomous Last-Mile Delivery Solutions',
  'platforms.logistics.detail': 'Hexacopter cargo platforms with 30-100kg+ payload capacity. Bypass terrain obstacles in mountainous or island regions, delivering 5x faster at 70% lower cost vs. helicopter transport. Powered by CANI Digital HD Link for stable range monitoring.',
  'platforms.logistics.anchor': 'Explore Heavy-Lift Cargo Drone Solutions',

  'platforms.swarm.title': 'UAV Swarm Systems',
  'platforms.swarm.desc': 'Coordinated Multi-UAV Autonomous Operations',
  'platforms.swarm.detail': 'Decentralized intelligence with per-unit AI obstacle avoidance and real-time position alignment. Scale to hundreds of UAVs for large-area search & rescue, agricultural spraying, or synchronized inspection missions.',
  'platforms.swarm.anchor': 'Explore Autonomous Swarm Technology',

  'platforms.fpv.title': 'Industrial FPV Inspection Drones',
  'platforms.fpv.desc': 'Compact Confined-Space Entry with Digital HD FPV',
  'platforms.fpv.detail': 'Ultra-agile platforms capable of entering 30cm-diameter pipes, boiler internals, and bridge box girders. Digital HD FPV link (not analog) ensures crack-detection precision with zero-latency video return.',
  'platforms.fpv.anchor': 'Explore Industrial FPV Inspection Drones',

