  'platforms.crossLink.title': 'Looking for Core Components Instead?',
  'platforms.crossLink.desc': 'All CANI platforms are powered by our proprietary high-performance components. Visit the Component Center to explore individual modules for system integration or OEM projects.',
  'platforms.crossLink.components': 'Browse UAV Components & Modules',
  'platforms.crossLink.vtx': 'Explore 50km Digital HD Video Links',
