  'platforms.downloadGuide': 'Download 2026 UAV Platform Selection Guide (PDF)',

  'platforms.faq.title': 'Platform Selection FAQ',
  'platforms.faq.subtitle': 'Common questions about choosing the right industrial UAV platform for your mission',
  'platforms.faq.q1': 'What is the main difference between CANI Logistics Drones and Consumer Drones?',
  'platforms.faq.a1': 'CANI Logistics Drones feature redundant power systems, heavy-lift hexacopter airframes, and AES-256 encrypted digital links for industrial-grade payload delivery, whereas consumer drones lack the durability and payload capacity for commercial cargo missions.',
  'platforms.faq.q2': 'Can your Tethered Drones be mounted on a moving vehicle?',
  'platforms.faq.a2': 'Yes. Our tethered platforms support mobile vehicle-mounted deployment, enabling persistent "eyes-in-the-sky" during convoy protection or disaster area patrols without landing for battery swaps.',
  'platforms.faq.q3': 'How do I choose between a Swarm system and a single heavy-lift platform?',
  'platforms.faq.a3': 'Swarm systems excel at covering large areas simultaneously (search & rescue, agricultural spraying), while a single heavy-lift platform is better for concentrated payload delivery or continuous monitoring of a fixed point.',

  'platforms.cta.title': 'Find the Right UAV Platform for Your Mission',
  'platforms.cta.subtitle': 'Our engineering team provides end-to-end support from platform selection to system integration and field deployment.',
