  'camera.sj4000.feature.2.title': '1080P Full HD Video',
  'camera.sj4000.feature.2.desc': 'Records 1080P HD video at 1920×1080 resolution with WDR (Wide Dynamic Range) for realistic, natural footage.',
  'camera.sj4000.feature.3.title': 'WiFi Wireless Streaming',
  'camera.sj4000.feature.3.desc': 'Built-in WiFi enables real-time mobile preview, remote shutter control, and instant sharing via companion app.',
  'camera.sj4000.feature.4.title': '30m Waterproof Design',
  'camera.sj4000.feature.4.desc': 'Professional waterproof housing rated to 30m depth, suitable for all-weather UAV operations and water sports.',
  'camera.sj4000.feature.5.title': 'Versatile Mounting Accessories',
  'camera.sj4000.feature.5.desc': 'Bundled with a full set of mounts for helmets, bicycles, skateboards, and drone platforms to cover diverse scenarios.',
