  'softwarePage.pvInspection.anomaly.title': 'PV Anomaly Glossary',
  'softwarePage.pvInspection.anomaly.desc': 'Engineer-grade fault diagnosis reference covering major PV thermal imaging anomaly types and AI processing strategies.',
  'softwarePage.pvInspection.anomaly.hotspot.title': 'Hotspots',
  'softwarePage.pvInspection.anomaly.hotspot.desc': 'Localized overheating caused by cell damage, short circuits, or shadow obstruction. Temperature differentials exceeding 20°C are classified as high-risk faults, automatically flagged with priority repair work orders.',
  'softwarePage.pvInspection.anomaly.string.title': 'String Outages',
  'softwarePage.pvInspection.anomaly.string.desc': 'Abnormal temperature rise or fall across entire panel rows, typically related to electrical connections, breakers, or inverter issues. These faults have the highest IRR impact (up to 249 basis points) and are top O&M priority.',
  'softwarePage.pvInspection.anomaly.diode.title': 'Bypass Diode Anomalies',
  'softwarePage.pvInspection.anomaly.diode.desc': 'Causes 1/3 of a panel area to overheat. The software uses zoned thermal analysis to precisely locate these faults, distinguishing between diode short-circuit and open-circuit modes.',
  'softwarePage.pvInspection.anomaly.soiling.title': 'Soiling & Shading',
  'softwarePage.pvInspection.anomaly.soiling.desc': 'Efficiency loss from dust accumulation, vegetation obstruction, or snow. RGB and IR dual-spectrum comparative analysis automatically generates cleaning recommendations and economic assessments.',
  'softwarePage.pvInspection.anomaly.crack.title': 'Microcracks',
  'softwarePage.pvInspection.anomaly.crack.desc': 'Internal micro-fractures in cells that initially do not affect generation but expand with thermal cycling. EL detection + thermal imaging combined analysis enables early warning.',
  'softwarePage.pvInspection.anomaly.junction.title': 'Junction Box Faults',
  'softwarePage.pvInspection.anomaly.junction.desc': 'Junction box overheating typically caused by loose connections or seal failure. Thermal imaging detects significant temperature rise areas to prevent fire risk.',

  'softwarePage.pvInspection.defects.title': 'AI Defect Recognition Capabilities',
  'softwarePage.pvInspection.defects.desc': 'System processes 10,000+ thermal images daily per 100MW farm with CNN deep learning models, automatically identifying 6+ PV component defect types at over 95% accuracy.',
  'softwarePage.pvInspection.d1': 'Hotspot Defects (ΔT ≥20°C high-risk flagging)',
  'softwarePage.pvInspection.d2': 'Microcracks (EL+IR combined detection)',
  'softwarePage.pvInspection.d3': 'String Faults (IRR impact ≤249bp diagnosis)',
  'softwarePage.pvInspection.d4': 'Bypass Diode Anomalies (1/3 panel localization)',
  'softwarePage.pvInspection.d5': 'Soiling & Shading (RGB/IR dual-spectrum analysis)',
  'softwarePage.pvInspection.d6': 'Junction Box Overheating (fire risk alert)',

