  'softwarePage.pvSystem.faq.q1': 'Which inverter brands does the platform support?',
  'softwarePage.pvSystem.faq.a1': 'The platform is compatible with mainstream inverter brands including Huawei, Sungrow, SMA, ABB, and Ginlong via standardized Modbus/TCP and API interfaces for automated data collection. Direct data logger integration is also supported.',
  'softwarePage.pvSystem.faq.q2': 'How does the system calculate and monitor Performance Ratio (PR)?',
  'softwarePage.pvSystem.faq.a2': 'The system uses weather station data (irradiance, temperature, wind speed) to correct theoretical generation, calculating real-time PR values. When PR deviation exceeds set thresholds, the system auto-triggers alerts and locates anomalous strings or inverters.',
  'softwarePage.pvSystem.faq.q3': 'Does it support multi-site enterprise management?',
  'softwarePage.pvSystem.faq.a3': 'Yes. The platform supports unlimited site access with enterprise-wide overview dashboards and tiered access control. HQ can view global asset summaries while local O&M staff access only their assigned site data.',
  'softwarePage.pvSystem.faq.q4': 'Are generated reports IEC-compliant?',
  'softwarePage.pvSystem.faq.a4': 'The system auto-generates IEC 61724-compliant performance reports covering PR analysis, loss decomposition (equipment/shading/degradation/weather), generation forecast deviation, and improvement recommendations. Reports export in PDF/Excel format.',

  'softwarePage.pvSystem.cta.title': 'Enter the Era of Smart Solar Asset Management',
