  'softwarePage.swarm.faq.title': 'Swarm Control Technical FAQ',
  'softwarePage.swarm.faq.q1': 'What is the core advantage of the sMatrix edge computing module?',
  'softwarePage.swarm.faq.a1': 'sMatrix is CANI\'s proprietary onboard edge computing module. Each UAV carries an independent AI decision unit for decentralized swarm coordination. Even if ground station communication is lost, the swarm maintains formation, obstacle avoidance, and mission execution autonomously, greatly enhancing mission reliability in complex electromagnetic environments.',
  'softwarePage.swarm.faq.q2': 'How does the auto-succession system work?',
  'softwarePage.swarm.faq.a2': 'When a UAV in the swarm needs to exit due to fault or low battery, the system automatically dispatches a replacement from the standby fleet, seamlessly taking over the departing UAV\'s mission role and route position. The entire process requires zero human intervention and zero mission interruption, ensuring continuity for large-scale SAR and inspection missions.',
  'softwarePage.swarm.faq.q3': 'How does the system maintain swarm navigation in GNSS-denied environments?',
  'softwarePage.swarm.faq.a3': 'CANI Swarm GCS supports multi-source fusion navigation. In GNSS-jammed or obstructed environments, it maintains formation accuracy through Visual-Inertial Odometry (VIO), UWB positioning, and inter-UAV relative positioning algorithms, ensuring reliable operation in urban canyons, indoor, and EMI scenarios.',
  'softwarePage.swarm.faq.q4': 'How many UAVs can the Swarm GCS support simultaneously?',
  'softwarePage.swarm.faq.a4': 'CANI Swarm GCS currently supports 50+ UAV simultaneous formation control through sMatrix edge computing and mesh networking for low-latency coordination. The architecture scales to larger fleets for drone light shows (500+) and industrial swarm inspection (50-100 UAVs).',

  'softwarePage.swarm.cta.title': 'Get Industrial Swarm Control Solution',
  'softwarePage.swarm.cta.subtitle': 'Contact us for a CANI Swarm GCS enterprise demo and learn how sMatrix edge computing with AI autonomous algorithms enable intelligent large-scale UAV swarm operations.',

