  'customAccessories.faq.title': 'Accessories Custom R&D Technical FAQ',
  'customAccessories.faq.q1': 'What video transmission solutions do you offer?',
  'customAccessories.faq.a1': 'We provide 1080P HD digital video links with end-to-end latency under 30ms, supporting 50km ultra-long range operations, perfectly suited for Beyond Visual Line of Sight (BVLOS) missions. Using COFDM modulation technology with strong anti-interference capability and AES-256-GCM encryption protection.',
  'customAccessories.faq.q2': 'What is the compatibility of your accessories?',
  'customAccessories.faq.a2': 'Core accessories are deeply compatible with DJI PSDK, MAVLink, and STANAG 4586 international standard interfaces, supporting cross-platform seamless integration. We also provide complete Interface Control Documents (ICD) and SDK development manuals for third-party developer integration.',
  'customAccessories.faq.q3': 'Do you support custom R&D?',
  'customAccessories.faq.a3': 'Yes. We offer full-process OEM/ODM customization from PCB layout, structural modeling to extreme environment (-40°C to 60°C) simulation testing. Our 200+ R&D team covers embedded, hardware, software, and structural specialties with prototype delivery in as fast as 30 days.',
  'customAccessories.faq.q4': 'Are accessories certified for industrial use?',
  'customAccessories.faq.a4': 'All core accessories pass MIL-STD-461G electromagnetic compatibility testing and RTCA DO-160G vibration screening, with IP67 protection rating. Battery cycle life exceeds 500 cycles (80% capacity retention), well above the industry average of 300 cycles.',

  'customAccessories.cta.title': 'Start Your Accessories Custom Project',
  'customAccessories.cta.desc': 'Contact our expert team to discuss your customization needs — from concept design to mass production delivery, one-stop full-process service',
  'customAccessories.cta.consult': 'Get a Quote',

