  'customSoftware.bluf.title': 'Core Capabilities: Defining the Intelligent Hub for UAV Operations',
  'customSoftware.bluf.content': 'CANI Technology is committed to building a highly reliable industrial-grade UAV software ecosystem. We provide end-to-end GCS customization, automated mission planning, ≤30ms ultra-low latency video transmission algorithms, and cross-platform SDK integration. As a High-tech Enterprise, our software systems are deeply adapted for power line inspection, security monitoring, and smart logistics.',
  'customSoftware.gcs.title': 'Custom Ground Control Station (GCS) Configuration & Control Systems',
  'customSoftware.gcs.insight': 'In 2026 industrial operations, software intuitiveness and data synchronization efficiency are key to reducing operator error. CANI Technology transforms complex flight parameters into real-time, visual command interfaces through modular architecture.',
  'customSoftware.gcs.hw.title': 'High-Precision Hardware Configuration Management',
  'customSoftware.gcs.hw.sensor': 'Sensor 3D Calibration System',
  'customSoftware.gcs.hw.sensor.desc': 'Intuitive interactive interface supporting one-click 3D calibration of magnetometers, IMU, and accelerometers, ensuring flight safety in high-interference environments.',
  'customSoftware.gcs.hw.payload': 'Multi-Payload Coordinated Control',
  'customSoftware.gcs.hw.payload.desc': 'Supports concurrent control of IP67-rated IR gimbals and various pods, enabling real-time 1080P HD video streaming and dynamic parameter adjustment.',
  'customSoftware.gcs.auto.title': 'Automated Mission Execution & Algorithms',
  'customSoftware.gcs.auto.route': 'Intelligent Route Planning',
  'customSoftware.gcs.auto.route.desc': 'Supports auto-grid generation, corridor scanning (for power lines/pipelines), and orbit modeling modes, significantly improving surveying and inspection efficiency.',
  'customSoftware.gcs.auto.dynamic': 'Dynamic Command Dispatch',
  'customSoftware.gcs.auto.dynamic.desc': 'Allows real-time waypoint and mission logic modification during operations without landing to respond to emergencies.',
  'customSoftware.matrix.title': 'Future-Ready UAV Autonomy & Data Intelligence',
  'customSoftware.matrix.insight': 'The future competition lies in "edge computing" and "analytical intelligence." CANI software integrates edge AI modules for real-time environmental perception.',
