  'customPayload.types.interface.desc': 'Mechanical CAD models, electrical interface standards, and SDK libraries — 50% faster R&D cycle',

  'customPayload.swap.title': 'Technical Advantages: SWaP-C & Protocol Standards',
  'customPayload.swap.desc': 'CANI Technology strictly follows SWaP-C (Size, Weight, Power, Cost) optimization logic in custom R&D, ensuring optimal balance between payload performance and flight endurance.',
  'customPayload.swap.hw': 'Hardware Interface Standards',
  'customPayload.swap.hw.desc': 'Full E-Port standard support with ≤4A overcurrent protection and ≤500μF load capacitance optimization for flight safety.',
  'customPayload.swap.protocol': 'Deep Protocol Compatibility',
  'customPayload.swap.protocol.desc': 'Native MAVLink, ELRS, and DJI PSDK support for seamless integration with QGroundControl or DJI Pilot.',
  'customPayload.swap.emi': 'EMI/EMC Shielding',
  'customPayload.swap.emi.desc': 'Dedicated RF zone management for 37W high-power VTX ensuring zero interference with GNSS and IMU modules.',

  'customPayload.custom.title': 'Deep Custom R&D (OEM/ODM)',
  'customPayload.custom.insight': 'CANI Technology excels at solving the deep SWaP-C (Size, Weight, Power, Cost) balance challenges in industrial payload integration.',
