  // ===== About Page - SEO Bottom Content =====
  'about.seo.manufacturer.title': 'Industrial UAV Core Component Original Manufacturer',
  'about.seo.manufacturer.p1': 'CANI Technology is a leading Chinese original manufacturer (OEM) of industrial UAV core components. Since 2015, we have focused on independent R&D and mass production of RF modules, video transmission systems, and embedded flight control software. As an industry source supplier, we provide complete OEM/ODM solutions — from chip-level design to finished product delivery — to UAV integrators and airframe manufacturers in 30+ countries worldwide.',
  'about.seo.manufacturer.p2': 'Core products include 37W high-power COFDM digital video links (50km range), multi-band analog VTX series (A1/A2/A3), industrial-grade ELRS control links, EO/IR dual-sensor gimbal pods, STM32 flight controllers with 48kHz ESC modules, and 1000+ UAV swarm ground station software. All products undergo rigorous EMC compatibility testing and -20°C to +60°C wide-temperature reliability verification for power inspection, emergency response, surveying, and logistics applications.',
  'about.seo.manufacturer.p3': 'Unlike component distributors and OBM resellers, CANI operates a complete RF laboratory, SMT production line, and embedded software development team. We support full-cycle technical services from PCB schematic design, RF impedance matching, and firmware development to complete system integration testing. Our R&D capabilities span FHSS frequency hopping, AES-256 communication encryption, adaptive bitrate (ABR) video transmission, and MBD model-based development.',
